<?php
if(!defined('SCHOOLOS_SERVICES_LIBRARY')){header('Location: index.php?s=services&area=engagement');exit;}
function eg_schema():array{return [
 "CREATE TABLE IF NOT EXISTS eg_contacts(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,channel VARCHAR(20) NOT NULL,address VARCHAR(190) NOT NULL,verified TINYINT NOT NULL DEFAULT 0,evidence VARCHAR(500) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,user_id,channel)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_consents(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,channel VARCHAR(20) NOT NULL,purpose VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,recorded_by BIGINT UNSIGNED NOT NULL,evidence VARCHAR(500) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,user_id,channel,purpose)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,subject VARCHAR(200) NOT NULL,body TEXT NOT NULL,wa_template VARCHAR(120) NOT NULL DEFAULT '',wa_language VARCHAR(20) NOT NULL DEFAULT 'en',created_by BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_campaigns(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,kind VARCHAR(20) NOT NULL,audience VARCHAR(20) NOT NULL,class_id BIGINT UNSIGNED NULL,recipient_id BIGINT UNSIGNED NULL,purpose VARCHAR(20) NOT NULL,channels_json TEXT NOT NULL,template_id BIGINT UNSIGNED NULL,source_key VARCHAR(100) NULL,send_at DATETIME NOT NULL,event_at DATETIME NULL,ends_at DATETIME NULL,options_json TEXT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY source_once(tenant_id,source_key),INDEX(tenant_id,status,send_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_deliveries(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,channel VARCHAR(20) NOT NULL,subject VARCHAR(200) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'queued',units INT NOT NULL DEFAULT 0,provider_id VARCHAR(190) NULL,error_code VARCHAR(120) NULL,post_id BIGINT UNSIGNED NULL,claimed_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY once_delivery(tenant_id,campaign_id,user_id,channel),INDEX(tenant_id,status,id),INDEX(tenant_id,channel,provider_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_wallets(tenant_id BIGINT UNSIGNED PRIMARY KEY,units BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_credit_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,delta BIGINT NOT NULL,event_key VARCHAR(120) NOT NULL,reason VARCHAR(500) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_credit(tenant_id,event_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_votes(tenant_id BIGINT UNSIGNED NOT NULL,campaign_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,answer VARCHAR(180) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,campaign_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS eg_push(tenant_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,subscription_id VARCHAR(100) NOT NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,user_id),UNIQUE KEY push_subscription(subscription_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function eg_config(int $tid):array{global $c;$v=$c['school_services'][(string)$tid]??[];return array_replace(sv_secrets($tid),is_array($v)?$v:[]);}
function eg_setting_keys():array{return ['email_transport','resend_key','email_from','termii_key','sms_sender','whatsapp_token','whatsapp_phone_id','whatsapp_app_secret','whatsapp_verify_token','onesignal_key','onesignal_app_id'];}
function eg_scope(array $u,int $class):void{sv_own('classes',$u,$class);if(sv_can($u,'communications_manager'))return;if($u['role']!=='teacher'||!g('SELECT a.id FROM ac_allocations a JOIN classes c ON c.id=a.class_id AND c.tenant_id=a.tenant_id WHERE a.tenant_id=? AND a.teacher_id=? AND a.class_id=? AND a.session_name=c.session_name',[$u['tenant_id'],$u['id'],$class]))throw new RuntimeException('Class is not assigned to this teacher.');}
function eg_allowed(array $campaign,array $u):bool{if((int)$campaign['tenant_id']!==(int)$u['tenant_id'])return false;if($campaign['recipient_id']!==null)return (int)$campaign['recipient_id']===(int)$u['id'];$audience=$campaign['audience'];if($audience==='all')return true;if($audience==='parents')return $u['role']==='parent';if($audience==='students')return $u['role']==='student';if($audience==='teachers')return $u['role']==='teacher';if($audience==='staff')return in_array($u['role'],['staff','teacher','admissions'],true);return $audience==='class'&&$u['role']!=='school_admin'&&cmAllowed($campaign,$u['role'],(int)$u['id'],(int)$u['tenant_id']);}
function eg_audience_valid(array $campaign,array $u):bool{if(sv_can($u,'communications_manager'))return true;try{if($campaign['audience']!=='class'||json_decode($campaign['channels_json'],true)!==['inapp']||!in_array($campaign['kind'],['announcement','broadcast','event','poll'],true))return false;eg_scope($u,(int)$campaign['class_id']);return true;}catch(Throwable $e){return false;}}
function eg_consent(int $tid,int $uid,string $channel,string $purpose):bool{if($channel==='inapp')return true;$r=q("SELECT c.*,u.role FROM eg_consents c JOIN users u ON u.id=c.user_id AND u.tenant_id=c.tenant_id WHERE c.tenant_id=? AND c.user_id=? AND c.channel=? AND c.purpose=? AND c.status='granted' AND u.active=1",[$tid,$uid,$channel,$purpose])->fetch();if(!$r)return false;if($r['role']!=='student')return (int)$r['recorded_by']===$uid;$sid=cbStudentId($tid,$uid);return $sid>0&&(bool)g("SELECT l.id FROM ecosystem_links l JOIN users p ON p.id=l.user_id AND p.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.student_id=? AND l.user_id=? AND l.relation_type='parent' AND p.role='parent' AND p.active=1",[$tid,$sid,$r['recorded_by']]);}
function eg_credit(int $tid,int $delta,string $key,string $reason,int $actor):void{q('INSERT IGNORE INTO eg_wallets(tenant_id) VALUES(?)',[$tid]);$w=q('SELECT units FROM eg_wallets WHERE tenant_id=? FOR UPDATE',[$tid])->fetch();$old=q('SELECT delta FROM eg_credit_log WHERE tenant_id=? AND event_key=?',[$tid,$key])->fetch();if($old){if((int)$old['delta']!==$delta)throw new RuntimeException('Credit reference differs.');return;}if((int)$w['units']+$delta<0)throw new RuntimeException('Insufficient messaging credits.');q('INSERT INTO eg_credit_log(tenant_id,delta,event_key,reason,created_by) VALUES(?,?,?,?,?)',[$tid,$delta,$key,$reason,$actor]);q('UPDATE eg_wallets SET units=units+? WHERE tenant_id=?',[$delta,$tid]);}
function eg_enqueue(int $tid,int $id):int{return sv_tx(function()use($tid,$id){$campaign=q('SELECT * FROM eg_campaigns WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();if(!$campaign||$campaign['status']!=='scheduled'||$campaign['send_at']>date('Y-m-d H:i:s'))return 0;$creator=q('SELECT * FROM users WHERE tenant_id=? AND id=? AND active=1',[$tid,$campaign['created_by']])->fetch();if(!$creator||!eg_audience_valid($campaign,$creator)){q("UPDATE eg_campaigns SET status='cancelled' WHERE tenant_id=? AND id=?",[$tid,$id]);return 0;}$school=(string)g('SELECT name FROM tenants WHERE id=?',[$tid]);$count=0;foreach(q('SELECT * FROM users WHERE tenant_id=? AND active=1 ORDER BY id',[$tid])->fetchAll() as $recipient){if(!eg_allowed($campaign,$recipient))continue;foreach(json_decode($campaign['channels_json'],true) as $channel){$replace=['{{name}}'=>$recipient['name'],'{{school}}'=>$school];q('INSERT IGNORE INTO eg_deliveries(tenant_id,campaign_id,user_id,channel,subject,body) VALUES(?,?,?,?,?,?)',[$tid,$id,$recipient['id'],$channel,mb_substr(strtr($campaign['title'],$replace),0,200),strtr($campaign['body'],$replace)]);$count++;}}q("UPDATE eg_campaigns SET status='queued' WHERE tenant_id=? AND id=?",[$tid,$id]);return $count;});}
function eg_community_email(array $u,array $post,string $email):int{sv_need($u,'communications_manager');$recipients=q("SELECT u.* FROM users u JOIN eg_contacts c ON c.user_id=u.id AND c.tenant_id=u.tenant_id AND c.channel='email' AND c.verified=1 WHERE u.tenant_id=? AND u.active=1 AND c.address=?",[$u['tenant_id'],$email])->fetchAll();if(count($recipients)!==1||!eg_allowed($post,$recipients[0]))throw new RuntimeException('Choose one verified recipient in this announcement’s audience. Manage contacts in School Services.');$target=$recipients[0];$purpose=in_array($post['kind'],['newsletter','marketing'],true)?'marketing':'operational';if(!eg_consent((int)$u['tenant_id'],(int)$target['id'],'email',$purpose))throw new RuntimeException('Recipient has not granted email consent for this purpose.');return sv_tx(function()use($u,$post,$target,$purpose){$key='CM-'.$post['id'].'-'.$target['id'];$old=q('SELECT id FROM eg_campaigns WHERE tenant_id=? AND source_key=?',[$u['tenant_id'],$key])->fetch();if($old)return (int)$old['id'];q("INSERT INTO eg_campaigns(tenant_id,title,body,kind,audience,recipient_id,purpose,channels_json,source_key,send_at,status,created_by) VALUES(?,?,?,'announcement','recipient',?,?,?, ?,NOW(),'scheduled',?)",[$u['tenant_id'],$post['title'],$post['body'],$target['id'],$purpose,'["email"]',$key,$u['id']]);return (int)$GLOBALS['pdo']->lastInsertId();});}
/** Fixed provider endpoints, TLS verification, no redirects, no message/credential dumps. */
function eg_http(string $url,array $headers,array $payload):array{if(!function_exists('curl_init'))throw new LogicException('Messaging requires PHP cURL.');$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($payload,JSON_THROW_ON_ERROR),CURLOPT_HTTPHEADER=>array_merge(['Content-Type: application/json'],$headers),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_CONNECTTIMEOUT=>5,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_SSL_VERIFYPEER=>true,CURLOPT_SSL_VERIFYHOST=>2]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false||$status===0)throw new RuntimeException('Provider response uncertain.');return ['http'=>$status,'data'=>json_decode($body,true)?:[]];}
function eg_provider(array $d,array $campaign,array $cfg,string $address,?callable $transport=null):array{
 $http=$transport??'eg_http';$channel=$d['channel'];if($channel==='email'&&($cfg['email_transport']??'')==='legacy_smtp'){if($transport!==null){$r=$transport('legacy_smtp',[],['to'=>$address,'subject'=>$d['subject'],'body'=>$d['body']]);return ['status'=>($r['http']??0)===200?'accepted':'failed','provider_id'=>'SMTP-'.$d['tenant_id'].'-'.$d['id'],'error'=>null];}v23smtpSend($address,$d['subject'],$d['body']);return ['status'=>'accepted','provider_id'=>'SMTP-'.$d['tenant_id'].'-'.$d['id'],'error'=>null];}$headers=[];$payload=[];$url='';
 if($channel==='email'){$key=(string)($cfg['resend_key']??'');$from=(string)($cfg['email_from']??'');if(!$key||!filter_var($from,FILTER_VALIDATE_EMAIL))throw new LogicException('Email provider is not configured.');$url='https://api.resend.com/emails';$headers=['Authorization: Bearer '.$key,'Idempotency-Key: schoolos-'.$d['tenant_id'].'-'.$d['id']];$payload=['from'=>$from,'to'=>[$address],'subject'=>$d['subject'],'text'=>$d['body']];}
 elseif($channel==='sms'){$key=(string)($cfg['termii_key']??'');$sender=(string)($cfg['sms_sender']??'');if(!$key||!preg_match('/^[A-Za-z0-9 ]{1,11}$/D',$sender))throw new LogicException('SMS provider is not configured.');$url='https://api.ng.termii.com/api/sms/send';$payload=['api_key'=>$key,'to'=>$address,'from'=>$sender,'sms'=>$d['subject']."\n".$d['body'],'type'=>'plain','channel'=>'generic'];}
 elseif($channel==='whatsapp'){$key=(string)($cfg['whatsapp_token']??'');$phone=(string)($cfg['whatsapp_phone_id']??'');$tpl=q('SELECT * FROM eg_templates WHERE tenant_id=? AND id=?',[$d['tenant_id'],$campaign['template_id']])->fetch();if(!$key||!preg_match('/^\d{5,30}$/D',$phone)||!$tpl||!preg_match('/^[a-z0-9_]{1,120}$/D',$tpl['wa_template']))throw new LogicException('Configure WhatsApp Business and a Meta-approved template with one body parameter.');$url='https://graph.facebook.com/v23.0/'.$phone.'/messages';$headers=['Authorization: Bearer '.$key];$payload=['messaging_product'=>'whatsapp','to'=>$address,'type'=>'template','template'=>['name'=>$tpl['wa_template'],'language'=>['code'=>$tpl['wa_language']],'components'=>[['type'=>'body','parameters'=>[['type'=>'text','text'=>$d['subject']."\n".$d['body']]]]]]];}
 elseif($channel==='push'){$key=(string)($cfg['onesignal_key']??'');$appid=(string)($cfg['onesignal_app_id']??'');if(!$key||!preg_match('/^[a-f0-9-]{36}$/iD',$appid))throw new LogicException('Push provider is not configured.');$url='https://api.onesignal.com/notifications';$headers=['Authorization: Key '.$key];$payload=['app_id'=>$appid,'include_subscription_ids'=>[$address],'contents'=>['en'=>'You have a new school update. Sign in to SchoolOS.'],'headings'=>['en'=>'SchoolOS'],'idempotency_key'=>sprintf('%08x-0000-4000-8000-%012x',(int)$d['tenant_id'],(int)$d['id'])];}
 else throw new RuntimeException('Invalid delivery channel.');$r=$http($url,$headers,$payload);$status=(int)($r['http']??0);$data=$r['data']??[];$id=$channel==='whatsapp'?($data['messages'][0]['id']??''):($channel==='sms'?($data['message_id']??''):($data['id']??''));if($status>=200&&$status<300&&is_string($id)&&$id!=='')return ['status'=>'accepted','provider_id'=>mb_substr($id,0,190),'error'=>null];if($status>=400&&$status<500)return ['status'=>'failed','provider_id'=>null,'error'=>'provider_http_'.$status];return ['status'=>'unknown','provider_id'=>null,'error'=>'provider_response_uncertain'];
}
function eg_dispatch(int $tid,int $id,?callable $transport=null):void{
 global $pdo;$cost=['inapp'=>0,'email'=>1,'sms'=>2,'whatsapp'=>3,'push'=>1];$cfg=eg_config($tid);
 $claimed=sv_tx(function()use($tid,$id,$cost){$d=q('SELECT * FROM eg_deliveries WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();if(!$d||$d['status']!=='queued')return null;$c=q('SELECT * FROM eg_campaigns WHERE tenant_id=? AND id=?',[$tid,$d['campaign_id']])->fetch();$u=q('SELECT * FROM users WHERE tenant_id=? AND id=? AND active=1',[$tid,$d['user_id']])->fetch();$creator=$c?q('SELECT * FROM users WHERE tenant_id=? AND id=? AND active=1',[$tid,$c['created_by']])->fetch():false;$reason='';if(!$c||$c['status']==='cancelled'||!$u||!$creator||!eg_audience_valid($c,$creator)||!eg_allowed($c,$u))$reason='recipient_or_scope_changed';elseif(!eg_consent($tid,(int)$u['id'],$d['channel'],$c['purpose']))$reason='consent_not_granted';$address='';
  if(!$reason&&$d['channel']!=='inapp'){if($d['channel']==='push')$address=(string)g('SELECT subscription_id FROM eg_push WHERE tenant_id=? AND user_id=?',[$tid,$u['id']]);else{$contact=q('SELECT * FROM eg_contacts WHERE tenant_id=? AND user_id=? AND channel=? AND verified=1',[$tid,$u['id'],$d['channel']])->fetch();$address=(string)($contact['address']??'');}if($address==='')$reason='verified_contact_missing';}
  if($reason){q("UPDATE eg_deliveries SET status='suppressed',error_code=? WHERE tenant_id=? AND id=?",[$reason,$tid,$id]);return null;}
  if($d['channel']==='inapp'){q('INSERT INTO cm_posts(tenant_id,author_id,title,body,audience,recipient_id,kind,pinned) VALUES(?,?,?,?,?,?,?,?)',[$tid,$c['created_by'],$d['subject'],$d['body'],'all',$u['id'],$c['kind']==='emergency'?'emergency':'announcement',$c['kind']==='emergency'?1:0]);$post=(int)$GLOBALS['pdo']->lastInsertId();q("UPDATE eg_deliveries SET status='delivered',post_id=? WHERE tenant_id=? AND id=?",[$post,$tid,$id]);return null;}
  $units=$cost[$d['channel']];q('INSERT IGNORE INTO eg_wallets(tenant_id) VALUES(?)',[$tid]);q('SELECT units FROM eg_wallets WHERE tenant_id=? FOR UPDATE',[$tid]);if((int)g('SELECT units FROM eg_wallets WHERE tenant_id=?',[$tid])<$units)return null;eg_credit($tid,-$units,'SEND-'.$id,'Reserved for external dispatch',0);q("UPDATE eg_deliveries SET status='sending',units=?,claimed_at=NOW() WHERE tenant_id=? AND id=?",[$units,$tid,$id]);$d['units']=$units;return [$d,$c,$address];
 });if(!$claimed)return;[$d,$campaign,$address]=$claimed;
 // Recheck consent after claiming and before provider I/O; a later revocation cannot recall an accepted message.
 if(!eg_consent($tid,(int)$d['user_id'],$d['channel'],$campaign['purpose'])){$result=['status'=>'suppressed','provider_id'=>null,'error'=>'consent_revoked'];}
 else{try{$result=eg_provider($d,$campaign,$cfg,$address,$transport);}catch(LogicException $e){$result=['status'=>'failed','provider_id'=>null,'error'=>'provider_configuration_missing'];}catch(Throwable $e){$result=['status'=>'unknown','provider_id'=>null,'error'=>'configuration_or_transport_uncertain'];}}
 sv_tx(function()use($tid,$id,$d,$result){$r=q('SELECT status FROM eg_deliveries WHERE tenant_id=? AND id=? FOR UPDATE',[$tid,$id])->fetch();if(!$r||$r['status']!=='sending')return;q('UPDATE eg_deliveries SET status=?,provider_id=?,error_code=? WHERE tenant_id=? AND id=?',[$result['status'],$result['provider_id'],$result['error'],$tid,$id]);if(in_array($result['status'],['failed','suppressed'],true))eg_credit($tid,(int)$d['units'],'REFUND-'.$id,'Definitively rejected or consent revoked before send',0);});
}
function eg_run(int $tid,int $limit=30,?callable $transport=null):int{if($tid<1||$limit<1||$limit>100)throw new RuntimeException('Invalid worker scope/limit.');$lock='schoolos-eg-'.substr(hash('sha256',(string)g('SELECT DATABASE()')),0,16).'-'.$tid;if(!(int)g('SELECT GET_LOCK(?,0)',[$lock]))throw new RuntimeException('Another worker is processing this school.');try{foreach(q("SELECT id FROM eg_campaigns WHERE tenant_id=? AND status='scheduled' AND send_at<=NOW() ORDER BY id LIMIT 50",[$tid])->fetchAll() as $r)eg_enqueue($tid,(int)$r['id']);$rows=q("SELECT id FROM eg_deliveries WHERE tenant_id=? AND status='queued' ORDER BY (channel='inapp') DESC,id LIMIT ".(int)$limit,[$tid])->fetchAll();foreach($rows as $d)eg_dispatch($tid,(int)$d['id'],$transport);q("UPDATE eg_campaigns c SET status='completed' WHERE c.tenant_id=? AND c.status='queued' AND NOT EXISTS(SELECT 1 FROM eg_deliveries d WHERE d.tenant_id=c.tenant_id AND d.campaign_id=c.id AND d.status IN ('queued','sending'))",[$tid]);return count($rows);}finally{q('SELECT RELEASE_LOCK(?)',[$lock]);}}
function eg_action(array $u,string $a):string{
 $tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$manager=sv_can($u,'communications_manager');
 if($a==='consent'){$target=op_id('user_id')?:$uid;$account=sv_own('users',$u,$target);$guardian=false;if($target!==$uid){if($u['role']!=='parent'||$account['role']!=='student')throw new RuntimeException('Only an explicitly linked parent may record a child account’s consent.');$sid=cbStudentId($tid,$target);op_child($u,$sid);$guardian=true;}if($account['role']==='student'&&!$guardian)throw new RuntimeException('A linked parent must manage the student’s external-channel consent.');$channel=sv_enum('channel',['email','sms','whatsapp','push']);$purpose=sv_enum('purpose',['operational','marketing']);$status=sv_enum('status',['granted','revoked']);q('INSERT INTO eg_consents(tenant_id,user_id,channel,purpose,status,recorded_by,evidence) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),recorded_by=VALUES(recorded_by),evidence=VALUES(evidence)',[$tid,$target,$channel,$purpose,$status,$uid,$guardian?'Explicit linked-parent choice':'Explicit account-holder choice']);audit('communications.consent.'.$status,'user',$target.' '.$channel.' '.$purpose);return 'Consent updated. Queued messages recheck it before sending.';}
 if($a==='contact'){$channel=sv_enum('channel',['email','sms','whatsapp']);$address=op_text('address',190,true);if($channel==='email'){if(!filter_var($address,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Invalid email address.');}else{$address=cmPhone($address);if(!$address)throw new RuntimeException('Use an international phone number.');}q('INSERT INTO eg_contacts(tenant_id,user_id,channel,address,verified,evidence) VALUES(?,?,?,?,0,?) ON DUPLICATE KEY UPDATE address=VALUES(address),verified=0,evidence=VALUES(evidence)',[$tid,$uid,$channel,$address,'Account-holder submission; verification pending']);return 'Contact submitted. School staff must verify ownership before external delivery.';}
 if($a==='push_remove'){q('DELETE FROM eg_push WHERE tenant_id=? AND user_id=?',[$tid,$uid]);return 'Saved push subscription removed. Also disable browser/provider notification permission if desired.';}
 if($a==='push'){$id=op_text('subscription_id',100,true);if(!preg_match('/^[a-f0-9-]{36}$/iD',$id))throw new RuntimeException('Enter your OneSignal browser subscription UUID.');q('INSERT INTO eg_push(tenant_id,user_id,subscription_id) VALUES(?,?,?) ON DUPLICATE KEY UPDATE subscription_id=IF(tenant_id=VALUES(tenant_id) AND user_id=VALUES(user_id),VALUES(subscription_id),subscription_id)',[$tid,$uid,$id]);return 'Push subscription recorded. Grant push consent separately. Push contains only a generic sign-in reminder.';}
 if($a==='vote'){return sv_tx(function()use($u,$tid,$uid){$p=sv_own('eg_campaigns',$u,op_id('campaign_id'),true);if($p['kind']!=='poll'||in_array($p['status'],['draft','cancelled'],true)||$p['send_at']>date('Y-m-d H:i:s')||($p['ends_at']&&$p['ends_at']<date('Y-m-d H:i:s'))||!eg_allowed($p,$u))throw new RuntimeException('Poll unavailable.');$answer=op_text('answer',180,true);if(!in_array($answer,json_decode($p['options_json'],true)?:[],true))throw new RuntimeException('Choose one listed option.');q('INSERT INTO eg_votes VALUES(?,?,?, ?,CURRENT_TIMESTAMP)',[$tid,$p['id'],$uid,$answer]);return 'Vote recorded once.';});}
 if($a==='message'){if($u['role']==='parent'){$_POST['pp_action']='message';$_POST['child']=op_id('student_id');return pp_action(pp_actor());}if($u['role']==='teacher'){$_POST['lp_action']='message';return lp_action(lp_actor());}throw new RuntimeException('Use Family Space for school-admin message review.');}
