function eg_webhook(int $tid,string $raw,string $signature):int{$cfg=eg_config($tid);$secret=(string)($cfg['whatsapp_app_secret']??'');if(!$secret||strlen($raw)>262144||!hash_equals('sha256='.hash_hmac('sha256',$raw,$secret),$signature))throw new RuntimeException('Invalid webhook signature.');$json=json_decode($raw,true,64,JSON_THROW_ON_ERROR);if(($json['object']??'')!=='whatsapp_business_account')throw new RuntimeException('Invalid WhatsApp event.');$count=0;foreach($json['entry']??[] as $entry)foreach($entry['changes']??[] as $change){$v=$change['value']??[];if((string)($v['metadata']['phone_number_id']??'')!==(string)($cfg['whatsapp_phone_id']??''))continue;foreach($v['statuses']??[] as $s){$status=$s['status']??'';if(!in_array($status,['sent','delivered','read','failed'],true))continue;$count+=sv_tx(function()use($tid,$s,$status){$r=q("SELECT * FROM eg_deliveries WHERE tenant_id=? AND channel='whatsapp' AND provider_id=? FOR UPDATE",[$tid,(string)($s['id']??'')])->fetch();if(!$r)return 0;$rank=['accepted'=>0,'sent'=>1,'delivered'=>2,'read'=>3];if(in_array($r['status'],['delivered','read'],true)&&($status==='failed'||($rank[$status]??-1)<=($rank[$r['status']]??-1)))return 0;if($r['status']==='failed'||($status!=='failed'&&($rank[$status]??-1)<=($rank[$r['status']]??-1)))return 0;q('UPDATE eg_deliveries SET status=? WHERE tenant_id=? AND id=?',[$status,$tid,$r['id']]);return 1;});}}return $count;}
